lemma complexifiedAction_one_add_smul_one {t : ℂT(c)}
    (ht : t ∈ (complexLorentzTensor.tensorRep c).invariants) (z : ℂ) :
    complexifiedAction c (unipotentLine hG z, 1) t = t

lemma complexifiedAction_mk_one_apply (hc : ∀ i, c i ≠ .up ∧ c i ≠ .down) {t : ℂT(c)}
    (ht : t ∈ (complexLorentzTensor.tensorRep c).invariants) (M : SL(2,ℂ)) :
    complexifiedAction c (M, 1) t = t

lemma reducesInvariantsTo_bot_leftRight {k k' : complexLorentzTensor.Color}
    (hk : (k = .upL ∧ k' = .upR) ∨ (k = .downL ∧ k' = .downR)) {B : Type*} [AddCommGroup B]
    [Module ℂ B] {repLorentz : Representation ℂ SL(2,ℂ) B} {f : ℂT[k, k'] →ₗ[ℂ] B}
    (hf : complexLorentzTensor.IsEquivariant ![k, k'] repLorentz f) :
    ReducesInvariantsTo (fun g : SL(2,ℂ) => repLorentz g) (LinearMap.range f) ⊥

lemma map_offDiagonal_eq_zero_of_invariant
    (hF : ∀ (M : SL(2,ℂ)) Y, F (M.1 * Y * M.1ᵀ) = ρ M (F Y)) {c : ℂ}
    (hc : ∀ g, ρ g (F !![0, c; c, 0]) = F !![0, c; c, 0]) : F !![0, c; c, 0] = 0

lemma map_eq_smul_map_metricRaw_of_invariant
    (hF : ∀ (M : SL(2,ℂ)) Y, F (M.1 * Y * M.1ᵀ) = ρ M (F Y)) {X : Matrix (Fin 2) (Fin 2) ℂ}
    (hX : ∀ g, ρ g (F X) = F X) : F X = ((X 0 1 - X 1 0) / 2) • F metricRaw

lemma symm_act_eq {ρV : Representation ℂ SL(2,ℂ) V} {ρW : Representation ℂ SL(2,ℂ) W}
    {Y : Matrix (Fin 2) (Fin 2) ℂ} (hY : (tensorToMatrix b c).symm Y ∈ (ρV.tprod ρW).invariants)
    {Φ : Matrix (Fin 2) (Fin 2) ℂ → Matrix (Fin 2) (Fin 2) ℂ}
    (h : ∃ g, ∀ X, LinearMap.toMatrix b b (ρV g) * X * (LinearMap.toMatrix c c (ρW g))ᵀ = Φ X) :
    (tensorToMatrix b c).symm (Φ Y) = (tensorToMatrix b c).symm Y

lemma infinitesimalAct_eq_zero_of_invariant {n : ℕ} {C : (Fin n → Fin 2) → ℂ}
    (hC : ∀ M : SL(2,ℂ), act M.1 C = C) :
    infinitesimalAct !![0, 1; 0, 0] C = 0 ∧ infinitesimalAct !![0, 0; 1, 0] C = 0

lemma eq_sum_pairingBasis_of_infinitesimalAct_eq_zero {C : (Fin 4 → Fin 2) → ℂ}
    (hE : infinitesimalAct !![0, 1; 0, 0] C = 0) (hF : infinitesimalAct !![0, 0; 1, 0] C = 0) :
    C = ∑ i, C (pairingPoint i) • pairingBasis i

def upLPowFourIdx :
